use kima_ml::clap::window_offsets;

#[test]
fn invalid_duration_is_rejected() {
    for duration in [-1.0, f64::NAN, f64::INFINITY, f64::NEG_INFINITY] {
        assert_eq!(window_offsets(duration), None);
    }
}

#[test]
fn matches_pinned_upstream_function_on_fractional_and_boundary_durations() {
    // Generated by executing the pinned upstream function, without importing its
    // dependencies; decimal strings round-trip Python's binary64 results.
    for line in include_str!("fixtures/clap_offsets_upstream.csv").lines() {
        let values: Vec<f64> = line.split(',').map(|s| s.parse().unwrap()).collect();
        assert_eq!(window_offsets(values[0]).unwrap(), values[1..], "{line}");
    }
}

#[test]
fn upstream_default_offsets_cover_short_tiled_and_long_tracks() {
    for (duration, expected) in [
        (0.0, vec![0.0; 5]),
        (5.0, vec![0.0]),
        (19.0, vec![0.0]),
        (30.0, vec![0.0, 10.0, 20.0]),
        (40.0, vec![0.0, 10.0, 20.0, 30.0]),
        (50.0, vec![0.0, 10.0, 20.0, 30.0, 40.0]),
        (60.0, vec![0.0, 12.5, 25.0, 37.5, 50.0]),
        (100.0, vec![10.0, 30.0, 50.0, 70.0, 90.0]),
    ] {
        assert_eq!(window_offsets(duration), Some(expected), "{duration}");
    }
}
